#define NUM_LIGHTS 3

float noise(float x){
    return fract(sin(x)*145011.0);
}


// SDF shapes from Inigo Quilez's great article
// https://iquilezles.org/articles/distfunctions/
float sdf_sphere( vec3 p, float s )
{
  return length(p)-s;
}

float sdRoundBox( vec3 p, vec3 b, float r )
{
  vec3 q = abs(p) - b + r;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0) - r;
}

float sdCapsule( vec3 p, vec3 a, vec3 b, float r )
{
  vec3 pa = p - a, ba = b - a;
  float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
  return length( pa - ba*h ) - r;
}

float opSmoothUnion( float d1, float d2, float k )
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}

// Smooth duty cycle oscilation
float pwm_wave(in float x, in float dc){
    return fract(x) < dc? 1. : 0.;
}

float rise_and_fall_wave(in float x, in float k_rise){
  float k_fall = 1. - k_rise;
  float rise = smoothstep(0.,1.,fract(x)/k_rise);
  float fall = smoothstep(1.,0.,fract(x+k_fall)/k_fall);
  return pwm_wave(x, k_rise) > 0.? rise: fall;
}

#define M_PI 3.141592654
#define SPHERE_RADIUS 0.5
#define SPHERE_AB_TESSELATION vec2(20.,10.)
#define SPIKE_MAX_LENGTH 0.4
#define SPIKE_RADIUS 0.01

float sdf_scene(in vec3 p){

  vec3 sphere_center = vec3(0.);
  float sphere = sdf_sphere(p - sphere_center, SPHERE_RADIUS);

  float res = sphere;
  vec2 da = 2. * M_PI / SPHERE_AB_TESSELATION;

  vec3 ps = p - sphere_center;
  float a = atan(ps.y, length(ps.xz));
  float b = atan(ps.z, p.x);

  for(int i = int(floor(a/da.x)); i <= int(ceil(a/da.x)); i++){
    for(int j = int(floor(b/da.y)); j <= int(ceil(b/da.y)); j++){
      float a = float(i) * da.x;
      float b = float(j) * da.y;
      vec3 psk = vec3(
        SPHERE_RADIUS * cos(a) * cos(b),
        SPHERE_RADIUS * sin(a),
        SPHERE_RADIUS * cos(a) * sin(b)
      );

      float spike_length = SPIKE_MAX_LENGTH * (0.5 + sin(mod(iTime,2.*M_PI) * 5. * noise(a*b) + 10. * noise(a*b))/2.);
      float spike = sdCapsule(p, psk, psk * (1.+ spike_length / length(psk)), SPIKE_RADIUS);
      res = opSmoothUnion(res, spike, 0.08);
    }
  }

  return res;

}

#define RAYMARCHING_MAX_STEPS 100
#define RAYMARCHING_RAY_TERMINATION 40.
#define RAYMARCHING_TOLLERANCE 0.001
float raymarch(in vec3 co, in vec3 rd){
  float depth = 0.0;
  // march ray
  for(int i = 0; i < RAYMARCHING_MAX_STEPS; i++){
    float dist = sdf_scene(co + depth * rd);
    if (dist < RAYMARCHING_TOLLERANCE){
      return depth;
    }
    // keep marhing ray
    depth += dist;

    if (depth >= RAYMARCHING_RAY_TERMINATION){
      return RAYMARCHING_RAY_TERMINATION;
    }
  }

  return RAYMARCHING_RAY_TERMINATION;
}

#define NORMALS_D 0.0001
vec3 compute_normal(in vec3 p){
  vec3 dx = vec3(NORMALS_D,0.,0.);
  vec3 dy = vec3(0.,NORMALS_D,0.);
  vec3 dz = vec3(0.,0.,NORMALS_D);
  return normalize(vec3(
    sdf_scene(p + dx) - sdf_scene(p - dx),
    sdf_scene(p + dy) - sdf_scene(p - dy),
    sdf_scene(p + dz) - sdf_scene(p - dz)
  ));
}

struct Light{
  float lr;
  float li;
  vec3 lp;
  vec3 lc;
};

#define OCCLUSION_DIST_TOLERANCE 0.1
bool compute_occlusion(in vec3 lp, in vec3 p){
  float depth = raymarch(lp,normalize(p-lp));
  return length(p-lp) > depth + OCCLUSION_DIST_TOLERANCE;
}

vec3 compute_light(in vec3 p, in vec3 pn, in vec3 pc, in float li, in vec3 lp, in vec3 lc){
  float lip = li / pow(length(p-lp), 2.);
  return lip * (lc + pc)/2. * clamp(dot(normalize(pn), normalize(lp-p)),0.,1.);
}

vec3 lighting(in vec3 p, in vec3 ro, in vec3 pd, in vec3 pn, in vec3 pc, in Light[NUM_LIGHTS] lights){
  vec3 color = vec3(0.);

  for(int i = 0; i < NUM_LIGHTS; i++){
    Light l = lights[i];

    // draw light
    if (abs(dot(normalize(pd),normalize(l.lp-ro)))  > 0.9999
    && length(p-l.lp) < 100000. + p.z + 0.01){
      return color = l.lc;
    }

    // // If light is occluded at that point do not add its contrinution
    if (compute_occlusion(l.lp,p)){
      continue;
    }
    color += compute_light(p, pn, pc, l.li, l.lp, l.lc);
  }
  return color ;
  // return pn;
}

mat3 setCamera( in vec3 ro, in vec3 ta, float cr )
{
	vec3 cw = normalize(ta-ro);
	vec3 cp = vec3(sin(cr), cos(cr),0.0);
	vec3 cu = normalize( cross(cw,cp) );
	vec3 cv =          ( cross(cu,cw) );
    return mat3( cu, cv, cw );
}


void mainImage(out vec4 fragColor, in vec2 fragCoord){
  vec2 mo = iMouse.xy/iResolution.xy;
  vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;
	float time = 32.0 + iTime*1.5;



  vec3 in_color = vec3(0.0941, 0.4353, 0.8863);
  vec3 out_color = vec3(0.8588, 0.7843, 0.6824);


  float sphere = sdf_sphere(vec3(p,0.), 0.5); 


  Light lights[NUM_LIGHTS];
  lights[0] = Light(0.1, 3., vec3(.8,3.,-.8), vec3(0.9255, 0.8824, 0.5059));
  lights[1] = Light(0.1, 2., vec3(-1.5,.5,0.), vec3(0.2863, 0.8863, 0.102));
  lights[2] = Light(0.1, 2., vec3(0.,.5,1.5), vec3(0.7882, 0.1412, 0.6471));

  // omnidirectional light
  float li = 5.;
  vec3 lp = vec3(0.);
  vec3 lc = vec3(0.9255, 0.8275, 0.5059);

  // camera	
  vec3 ta = .1*vec3( 0.,0.,0. );
  vec3 ro = ta + (mo.y + 0.2)*vec3( 4.5*cos(0.1*time + 7.0*mo.x), 5.2, 4.5*sin(0.1*time + 7.0*mo.x) );
  // camera-to-world transformation
  mat3 ca = setCamera( ro, ta, 0.0 );
  // focal length
  const float fl = 1.;  
  // ray direction
  vec3 rd = ca * normalize( vec3(p,fl) );



  float depth = raymarch(ro, rd);
  vec3 p3d = ro + rd * depth;

  vec3 material = depth < 1.? vec3(1.0, 1.0, 1.0) : vec3(1.);

  vec3 pn = compute_normal(p3d);
  vec3 color = lighting(p3d, ro, rd, pn, material, lights);

  // apply gamma correction
  float gamma = 2.2;
  color = pow(color, vec3(1.0/gamma));

  fragColor = vec4(color,1.);

}
